 arrow:'M6 18 18 6 M7 6h11v11',chevron:'m9 5 7 7-7 7',
 refresh:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 13-3l2 2 M19 16a8 8 0 0 1-13 3l-2-2',
 plus:'M12 5v14 M5 12h14',logout:'M9 3H4v18h5 M9 12h12 M16 7l5 5-5 5',
 shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z',
